valid = {'90': 90.0, '  42 ': 42.0, '7': 7.0, '0': 0.0, '2d': 172800.0, '3h': 10800.0, '15m': 900.0, '45s': 45.0, '500ms': 0.5, '1h30m': 5400.0, '2d4h': 187200.0, '1m1s': 61.0, '1s500ms': 1.5, '1d1h1m1s1ms': 90061.001, '1d1ms': 86400.001, '1h1s': 3601.0, ' 1h 30m ': 5400.0, '\t1h\n30m\u2003': 5400.0, '0s': 0.0, '0ms': 0.0, '0d0h0m0s0ms': 0.0, '00090': 90.0, '01h030m': 5400.0, '90m': 5400.0, '1500ms': 1.5, '\uff19\uff10': 90.0, '\uff11h\uff13\uff10m': 5400.0}
invalid = ['1 h', '1m  s', '1 ms', '\u00b2', '\u00b2s', '1h1h', '1ms 2ms', '0s0s', '30m1h', '1ms1s', '1s1d', '0ms0s', '', '   ', '\t\n', '-1', '-1h', '+1', '+1h', '1.5', '1.5h', '1e3', '1e3s', '1_000', '1_000s', '1x', '1H', '1MS', 'h', 'ms', 'abc', '1h30', '90 1s', '1s 90', '1 2', '1h,30m', '1h/30m', '1mss']
for parser in (parse_duration, direct):
    for value, expected in valid.items():
        actual = parser(value)
        assert isinstance(actual, float) and abs(actual - expected) <= 1e-9, (value, actual, expected)
    for value in invalid:
        try:
            parser(value)
        except ValueError:
            pass
        else:
            raise AssertionError(('accepted invalid', value))
    for value in (90, 0.5, None, True, b'90', [], {}):
        try:
            parser(value)
        except TypeError:
            pass
        else:
            raise AssertionError(('accepted non-string', value))
print('Contract examples passed for both import paths')

